 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 8 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, x in cells); r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells); c1 = max(x for y, x in cells)
            colored = [(y, x) for y, x in cells if grid[y][x] not in (0, 8)]
            if not colored:
                continue
            pr0 = min(y for y, x in colored); pr1 = max(y for y, x in colored)
            pc0 = min(x for y, x in colored); pc1 = max(x for y, x in colored)
            ph, pw = pr1 - pr0 + 1, pc1 - pc0 + 1
            pattern = [grid[pr0 + dy][pc0:pc0 + pw] for dy in range(ph)]
            for y, x in cells:
                out[y][x] = pattern[(y - pr0) % ph][(x - pc0) % pw]
    return out
